INSERT INTO summer_safety_2026_meta (key, value) VALUES ('ai_report', '毎回の点呼で居眠り運転のリスクを繰り返し周知したことにより、乗務員一人ひとりが普段以上に休憩を取り、漫然運転（ぼんやりした状態での運転）を意識的に避ける傾向が見られました。
