-- ===================================================
-- migration_134: 夏季の交通事故をゼロにする運動（2026）手札の集計
--
--   各乗務員が1日1回、当日の乗務での眠気について 1/2/3 を手札に記入。
--     1 = 眠気を感じなかった
--     2 = 眠気を感じたので運転を停止した
--     3 = 眠気を感じたが「これぐらいは大丈夫」と判断して運転を続けた
--   回収した手札67枚（2026年9月4日 集約）を初期データとして投入する。
--   数字は手書きスキャンからのAI下読みのため要確認（画面から個人別に修正可）。
--   課長ミッション →「夏季交通安全（2026）」で集計・週別傾向・個人別を表示。
-- ===================================================

CREATE TABLE IF NOT EXISTS summer_safety_2026_people (
  person_key  TEXT PRIMARY KEY,          -- 社員番号（無ければ s<手札番号>）
  emp_no      TEXT,
  emp_name    TEXT NOT NULL,
  team        INTEGER,
  division    INTEGER,
  sheet_no    INTEGER,                  -- 回収した手札の並び順
  updated_at  TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);

CREATE TABLE IF NOT EXISTS summer_safety_2026_entries (
  person_key  TEXT NOT NULL,
  day         INTEGER NOT NULL CHECK(day BETWEEN 1 AND 31),
  value       INTEGER NOT NULL CHECK(value BETWEEN 1 AND 3),
  updated_at  TEXT NOT NULL DEFAULT (datetime('now','localtime')),
  PRIMARY KEY (person_key, day)
);

CREATE INDEX IF NOT EXISTS idx_summer_safety_2026_entries_day ON summer_safety_2026_entries(day);

CREATE TABLE IF NOT EXISTS summer_safety_2026_meta (
  key         TEXT PRIMARY KEY,
  value       TEXT NOT NULL,
  updated_at  TEXT NOT NULL DEFAULT (datetime('now','localtime'))
);

また、「3」（眠気を感じたが運転を継続した）を選択した乗務員に対しては、その都度、当直・管理者が状況の聞き取りを行い、休憩の取り方や体調管理について個別に助言したため、重大な事故には至りませんでした。
期間中（2026年8月1日〜8月31日）の居眠り事故は0件です。')
  ON CONFLICT(key) DO NOTHING;


